const CIRCUITS=["club","melbourne","shanghai","suzuka","sakhir","jeddah","miami","montreal","monaco","barcelona","spielberg","silverstone","spa","budapest","zandvoort","monza","madrid","baku","singapore","austin","mexico","saopaulo","lasvegas","lusail","yasmarina","hanoi"];
export const EVENTS=['page_view','user_engagement','garage_view','member_car_view','member_instagram_click','gallery_open','gallery_image_view','gallery_album_view','event_view','event_calendar_click','event_save_calendar','event_location_click','marketplace_view','marketplace_listing_view','seller_contact_click','simulator_start','simulator_engagement','simulator_session_end','simulator_lap_complete','simulator_best_lap','video_start','video_progress','video_complete','club_button_click','site_search','contact_click','social_link_click','news_link_click'];
export const PAGES=['/','/index.html','/garaje.html','/galeria.html','/mercadillo.html','/simulador.html','/colaboradores.html','/redes-sociales.html','/normas-carretera.html'];
export function publicPage(value){try{const p=new URL(value,'https://octaviaap.pages.dev').pathname;const clean=p==='/'?'/':p.endsWith('.html')?p:p+'.html';return PAGES.includes(clean)?clean:null;}catch{return null;}}
export function safeParams(input={}){const p={};const enums={circuit:CIRCUITS,section:['club','garaje','galeria','calendario','mercadillo','simulador','colaboradores','redes','inicio','noticias','contacto'],button:['club','garaje','galeria','calendario','mercadillo','simulador','colaboradores','instagram','whatsapp','email','telegram','youtube','spotify','facebook','myskoda','phone','tiktok','discord','twitch','x','linkedin','other'],level:['easy','intermediate','expert'],state:['started','finished','reset','abandoned','paused'],progress:[25,50,75,100]};for(const [key,values]of Object.entries(enums))if(values.includes(input[key]))p[key]=input[key];for(const [key,min,max]of [['lap',1,3],['lap_ms',1,3600000],['active_ms',0,60000],['query_length',0,200],['results_count',0,10000]])if(Number.isFinite(input[key])&&input[key]>=min&&input[key]<=max)p[key]=Math.round(input[key]);for(const key of ['resource_id','album_id','listing_id'])if(typeof input[key]==='string'&&/^[0-9a-f]{8}-[0-9a-f-]{27}$/i.test(input[key]))p[key]=input[key];return p;}
